{"element_type_code":"WALL-001","mapping_source":"uniclass","ifc_class":null,"ifc_predefined_type":null,"uniclass_system":"Ss","uniclass_code":"Ss_25_10_32_70","bt_element_type_code":"WALL-001","notes":"Uniclass_status=PROPOSED; source_column=UNICLASS_SS; OmniClass_decision=OUT_OF_SCOPE; Reinforced concrete wall structure system current code. Product code not yet verified."},{"element_type_code":"FLOOR-001","mapping_source":"ifc","ifc_class":"IfcSlab","ifc_predefined_type":"FLOOR","uniclass_system":null,"uniclass_code":null,"bt_element_type_code":"FLOOR-001","notes":"IFC_status=PROPOSED; OmniClass_decision=OUT_OF_SCOPE; Product parent for concrete flooring/decking. System code for ground-bearing industrial slab still to research."},{"element_type_code":"FLOOR-001","mapping_source":"uniclass","ifc_class":null,"ifc_predefined_type":null,"uniclass_system":"Pr","uniclass_code":"Pr_20_85_14","bt_element_type_code":"FLOOR-001","notes":"Uniclass_status=NEEDS_REVIEW; source_column=UNICLASS_PR; OmniClass_decision=OUT_OF_SCOPE; Product parent for concrete flooring/decking. System code for ground-bearing industrial slab still to research."}]$m18$::jsonb) AS src(
        element_type_code TEXT,
        mapping_source TEXT,
        ifc_class TEXT,
        ifc_predefined_type TEXT,
        uniclass_system TEXT,
        uniclass_code TEXT,
        bt_element_type_code TEXT,
        notes TEXT
);

-- Preflight checks run before permanent catalog writes.
DO $$
DECLARE
    problem TEXT;
BEGIN
    SELECT string_agg(element_type_code || ' rows=' || rows, '; ' ORDER BY element_type_code)
    INTO problem
    FROM (
        SELECT element_type_code, string_agg(source_row::text, ',' ORDER BY source_row) AS rows
        FROM m18_seed_element_type
        GROUP BY element_type_code
        HAVING COUNT(*) > 1
    ) AS duplicates;
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source has duplicate element_type_code natural keys: %', problem;
    END IF;

    SELECT string_agg(matrix_kind || ':' || element_type_code || '/' || item_code || ' rows=' || rows, '; ' ORDER BY matrix_kind, element_type_code, item_code)
    INTO problem
    FROM (
        SELECT matrix_kind, element_type_code, item_code, string_agg(source_row::text, ',' ORDER BY source_row) AS rows
        FROM m18_seed_matrix_mark
        GROUP BY matrix_kind, element_type_code, item_code
        HAVING COUNT(*) > 1
    ) AS duplicates;
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source has duplicate matrix natural keys: %', problem;
    END IF;

    SELECT string_agg(matrix_kind || ' row=' || source_row || ' col=' || source_column || ' value=' || matrix_symbol, '; ' ORDER BY matrix_kind, source_row, source_column)
    INTO problem
    FROM m18_seed_matrix_mark
    WHERE matrix_symbol NOT IN ('★', '✓');
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source has unsupported matrix symbols. Only star/check are allowed: %', problem;
    END IF;

    SELECT string_agg(expected_code, ', ' ORDER BY expected_code)
    INTO problem
    FROM (SELECT 'P-' || LPAD(gs::text, 3, '0') AS expected_code FROM generate_series(1, 17) AS gs) AS expected
    LEFT JOIN m18_seed_property_definition AS src ON src.property_code = expected.expected_code
    WHERE src.property_code IS NULL;
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source is missing property codes: %', problem;
    END IF;

    SELECT string_agg(expected_code, ', ' ORDER BY expected_code)
    INTO problem
    FROM (SELECT 'L-' || LPAD(gs::text, 3, '0') AS expected_code FROM generate_series(1, 22) AS gs) AS expected
    LEFT JOIN m18_seed_activity_definition AS src ON src.activity_code = expected.expected_code
    WHERE src.activity_code IS NULL;
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source is missing activity codes: %', problem;
    END IF;

    SELECT string_agg(mapping_source || '/' || COALESCE(ifc_class, '') || '/' || COALESCE(ifc_predefined_type, '') || '/' || COALESCE(uniclass_system, '') || '/' || COALESCE(uniclass_code, ''), '; ')
    INTO problem
    FROM m18_seed_classification_mapping
    WHERE COALESCE(ifc_class, '') IN ('TBD', 'TO_RESEARCH', 'OUT_OF_SCOPE')
       OR COALESCE(ifc_predefined_type, '') IN ('TBD', 'TO_RESEARCH', 'OUT_OF_SCOPE')
       OR COALESCE(uniclass_code, '') IN ('TBD', 'TO_RESEARCH', 'OUT_OF_SCOPE')
       OR mapping_source = 'revit';
    IF problem IS NOT NULL THEN
        RAISE EXCEPTION 'migrate_18 source generated forbidden runtime classification mappings: %', problem;
    END IF;
END $$;

INSERT INTO catalog.element_type (element_type_code, element_type_name, discipline, description, default_unit_of_measure, catalog_version, attributes, is_active)
SELECT element_type_code, element_type_name, discipline, description, default_uom, 'draft',
       jsonb_strip_nulls(jsonb_build_object('material', material, 'status', status)), TRUE
FROM m18_seed_element_type
ON CONFLICT (element_type_code, catalog_version) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET element_type_name = EXCLUDED.element_type_name, discipline = EXCLUDED.discipline,
    description = EXCLUDED.description, default_unit_of_measure = EXCLUDED.default_unit_of_measure,
    attributes = EXCLUDED.attributes, is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.property_definition (property_code, property_name, value_type, unit_of_measure, allowed_values, source_standard, catalog_version, is_active)
SELECT property_code, property_name, value_type, unit_of_measure, '[]'::jsonb, source_system, 'draft', TRUE
FROM m18_seed_property_definition
ON CONFLICT (property_code, catalog_version) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET property_name = EXCLUDED.property_name, value_type = EXCLUDED.value_type,
    unit_of_measure = EXCLUDED.unit_of_measure, source_standard = EXCLUDED.source_standard,
    is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.activity_definition (activity_code, activity_name, description, quantity_basis, catalog_version, is_active)
SELECT activity_code, activity_name, description, quantity_basis, 'draft', TRUE
FROM m18_seed_activity_definition
ON CONFLICT (activity_code, catalog_version) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET activity_name = EXCLUDED.activity_name, description = EXCLUDED.description,
    quantity_basis = EXCLUDED.quantity_basis, is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.quality_requirement_definition (requirement_code, requirement_name, test_type, acceptance_criteria, catalog_version, is_active)
SELECT requirement_code, requirement_name, test_type, acceptance_criteria, 'draft', TRUE
FROM m18_seed_quality_definition
ON CONFLICT (requirement_code, catalog_version) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET requirement_name = EXCLUDED.requirement_name, test_type = EXCLUDED.test_type,
    acceptance_criteria = EXCLUDED.acceptance_criteria, is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.document_requirement_definition (requirement_code, requirement_name, doc_type, requirement_parameters, catalog_version, is_active)
SELECT requirement_code, requirement_name, doc_type, requirement_parameters, 'draft', TRUE
FROM m18_seed_document_definition
ON CONFLICT (requirement_code, catalog_version) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET requirement_name = EXCLUDED.requirement_name, doc_type = EXCLUDED.doc_type,
    requirement_parameters = EXCLUDED.requirement_parameters, is_active = TRUE, updated_at = NOW();

-- Scoped stale-applicability cleanup: only workbook element codes and workbook definition codes are affected.
DELETE FROM catalog.element_type_property_applicability AS app
USING catalog.element_type AS et, catalog.property_definition AS def
WHERE app.tenant_id IS NULL AND app.project_code IS NULL
  AND app.element_type_id = et.element_type_id
  AND app.property_definition_id = def.property_definition_id
  AND et.tenant_id IS NULL AND et.project_code IS NULL AND et.catalog_version = 'draft'
  AND def.tenant_id IS NULL AND def.project_code IS NULL AND def.catalog_version = 'draft'
  AND et.element_type_code IN (SELECT element_type_code FROM m18_seed_element_type)
  AND def.property_code IN (SELECT item_code FROM m18_seed_matrix_mark WHERE matrix_kind = 'property')
  AND NOT EXISTS (
      SELECT 1 FROM m18_seed_matrix_mark AS src
      WHERE src.matrix_kind = 'property'
        AND src.element_type_code = et.element_type_code
        AND src.item_code = def.property_code
  );

DELETE FROM catalog.element_type_activity_applicability AS app
USING catalog.element_type AS et, catalog.activity_definition AS def
WHERE app.tenant_id IS NULL AND app.project_code IS NULL
  AND app.element_type_id = et.element_type_id
  AND app.activity_definition_id = def.activity_definition_id
  AND et.tenant_id IS NULL AND et.project_code IS NULL AND et.catalog_version = 'draft'
  AND def.tenant_id IS NULL AND def.project_code IS NULL AND def.catalog_version = 'draft'
  AND et.element_type_code IN (SELECT element_type_code FROM m18_seed_element_type)
  AND def.activity_code IN (SELECT item_code FROM m18_seed_matrix_mark WHERE matrix_kind = 'activity')
  AND NOT EXISTS (
      SELECT 1 FROM m18_seed_matrix_mark AS src
      WHERE src.matrix_kind = 'activity'
        AND src.element_type_code = et.element_type_code
        AND src.item_code = def.activity_code
  );

DELETE FROM catalog.element_type_quality_applicability AS app
USING catalog.element_type AS et, catalog.quality_requirement_definition AS def
WHERE app.tenant_id IS NULL AND app.project_code IS NULL
  AND app.element_type_id = et.element_type_id
  AND app.quality_requirement_definition_id = def.quality_requirement_definition_id
  AND et.tenant_id IS NULL AND et.project_code IS NULL AND et.catalog_version = 'draft'
  AND def.tenant_id IS NULL AND def.project_code IS NULL AND def.catalog_version = 'draft'
  AND et.element_type_code IN (SELECT element_type_code FROM m18_seed_element_type)
  AND def.requirement_code IN (SELECT item_code FROM m18_seed_matrix_mark WHERE matrix_kind = 'quality')
  AND NOT EXISTS (
      SELECT 1 FROM m18_seed_matrix_mark AS src
      WHERE src.matrix_kind = 'quality'
        AND src.element_type_code = et.element_type_code
        AND src.item_code = def.requirement_code
  );

DELETE FROM catalog.element_type_document_applicability AS app
USING catalog.element_type AS et, catalog.document_requirement_definition AS def
WHERE app.tenant_id IS NULL AND app.project_code IS NULL
  AND app.element_type_id = et.element_type_id
  AND app.document_requirement_definition_id = def.document_requirement_definition_id
  AND et.tenant_id IS NULL AND et.project_code IS NULL AND et.catalog_version = 'draft'
  AND def.tenant_id IS NULL AND def.project_code IS NULL AND def.catalog_version = 'draft'
  AND et.element_type_code IN (SELECT element_type_code FROM m18_seed_element_type)
  AND def.requirement_code IN (SELECT item_code FROM m18_seed_matrix_mark WHERE matrix_kind = 'document')
  AND NOT EXISTS (
      SELECT 1 FROM m18_seed_matrix_mark AS src
      WHERE src.matrix_kind = 'document'
        AND src.element_type_code = et.element_type_code
        AND src.item_code = def.requirement_code
  );

INSERT INTO catalog.element_type_property_applicability (element_type_id, property_definition_id, is_required, sort_order, applicability_parameters, is_active)
SELECT et.element_type_id, def.property_definition_id, src.is_primary, src.sort_order,
       jsonb_build_object('matrix_symbol', src.matrix_symbol, 'is_primary', src.is_primary), TRUE
FROM m18_seed_matrix_mark AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
JOIN catalog.property_definition AS def ON def.property_code = src.item_code AND def.catalog_version = 'draft' AND def.tenant_id IS NULL AND def.project_code IS NULL
WHERE src.matrix_kind = 'property'
ON CONFLICT (element_type_id, property_definition_id) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET is_required = EXCLUDED.is_required, sort_order = EXCLUDED.sort_order,
    applicability_parameters = EXCLUDED.applicability_parameters, is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.element_type_activity_applicability (element_type_id, activity_definition_id, sequence_no, is_required, rule_parameters, is_active)
SELECT et.element_type_id, def.activity_definition_id, src.sort_order, src.is_primary,
       jsonb_build_object('matrix_symbol', src.matrix_symbol, 'is_primary', src.is_primary), TRUE
FROM m18_seed_matrix_mark AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
JOIN catalog.activity_definition AS def ON def.activity_code = src.item_code AND def.catalog_version = 'draft' AND def.tenant_id IS NULL AND def.project_code IS NULL
WHERE src.matrix_kind = 'activity'
ON CONFLICT (element_type_id, activity_definition_id) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET sequence_no = EXCLUDED.sequence_no, is_required = EXCLUDED.is_required,
    rule_parameters = EXCLUDED.rule_parameters, is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.element_type_quality_applicability (element_type_id, quality_requirement_definition_id, is_mandatory, applicability_parameters, is_active)
SELECT et.element_type_id, def.quality_requirement_definition_id, src.is_primary,
       jsonb_build_object('matrix_symbol', src.matrix_symbol, 'is_primary', src.is_primary), TRUE
FROM m18_seed_matrix_mark AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
JOIN catalog.quality_requirement_definition AS def ON def.requirement_code = src.item_code AND def.catalog_version = 'draft' AND def.tenant_id IS NULL AND def.project_code IS NULL
WHERE src.matrix_kind = 'quality'
ON CONFLICT (element_type_id, quality_requirement_definition_id) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET is_mandatory = EXCLUDED.is_mandatory, applicability_parameters = EXCLUDED.applicability_parameters,
    is_active = TRUE, updated_at = NOW();

INSERT INTO catalog.element_type_document_applicability (element_type_id, document_requirement_definition_id, is_mandatory, applicability_parameters, is_active)
SELECT et.element_type_id, def.document_requirement_definition_id, src.is_primary,
       jsonb_build_object('matrix_symbol', src.matrix_symbol, 'is_primary', src.is_primary), TRUE
FROM m18_seed_matrix_mark AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
JOIN catalog.document_requirement_definition AS def ON def.requirement_code = src.item_code AND def.catalog_version = 'draft' AND def.tenant_id IS NULL AND def.project_code IS NULL
WHERE src.matrix_kind = 'document'
ON CONFLICT (element_type_id, document_requirement_definition_id) WHERE tenant_id IS NULL AND project_code IS NULL
DO UPDATE SET is_mandatory = EXCLUDED.is_mandatory, applicability_parameters = EXCLUDED.applicability_parameters,
    is_active = TRUE, updated_at = NOW();

-- Classification mappings are explicit. REVIT_CATEGORY is intentionally not inserted as mapping_source = 'revit'.
UPDATE catalog.element_type_classification_mapping AS dst
SET bt_element_type_code = src.bt_element_type_code, notes = src.notes, is_active = TRUE, updated_at = NOW()
FROM m18_seed_classification_mapping AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
WHERE dst.tenant_id IS NULL
  AND dst.project_code IS NULL
  AND dst.element_type_id = et.element_type_id
  AND dst.mapping_source = src.mapping_source
  AND COALESCE(dst.revit_category, '') = ''
  AND COALESCE(dst.revit_family, '') = ''
  AND COALESCE(dst.revit_type, '') = ''
  AND COALESCE(dst.ifc_class, '') = COALESCE(src.ifc_class, '')
  AND COALESCE(dst.ifc_predefined_type, '') = COALESCE(src.ifc_predefined_type, '')
  AND COALESCE(dst.uniclass_system, '') = COALESCE(src.uniclass_system, '')
  AND COALESCE(dst.uniclass_code, '') = COALESCE(src.uniclass_code, '');

INSERT INTO catalog.element_type_classification_mapping (element_type_id, mapping_source, ifc_class, ifc_predefined_type, uniclass_system, uniclass_code, bt_element_type_code, notes, is_active)
SELECT et.element_type_id, src.mapping_source, src.ifc_class, src.ifc_predefined_type, src.uniclass_system, src.uniclass_code, src.bt_element_type_code, src.notes, TRUE
FROM m18_seed_classification_mapping AS src
JOIN catalog.element_type AS et ON et.element_type_code = src.element_type_code AND et.catalog_version = 'draft' AND et.tenant_id IS NULL AND et.project_code IS NULL
WHERE NOT EXISTS (
    SELECT 1
    FROM catalog.element_type_classification_mapping AS dst
    WHERE dst.tenant_id IS NULL
        AND dst.project_code IS NULL
        AND dst.element_type_id = et.element_type_id
        AND dst.mapping_source = src.mapping_source
        AND COALESCE(dst.revit_category, '') = ''
        AND COALESCE(dst.revit_family, '') = ''
        AND COALESCE(dst.revit_type, '') = ''
        AND COALESCE(dst.ifc_class, '') = COALESCE(src.ifc_class, '')
        AND COALESCE(dst.ifc_predefined_type, '') = COALESCE(src.ifc_predefined_type, '')
        AND COALESCE(dst.uniclass_system, '') = COALESCE(src.uniclass_system, '')
        AND COALESCE(dst.uniclass_code, '') = COALESCE(src.uniclass_code, '')
);

COMMIT;

